        cases.generates(null, "(01)12312312312326(21)abc123", "https://id.gs1.org/01/12312312312326/21/abc123")
        cases.generates("https://example.com", "(01)12312312312326(21)abc123", "https://example.com/01/12312312312326/21/abc123")
        cases.generates("https://example.com", "(01)12312312312326(22)ABC(10)DEF(21)GHI", "https://example.com/01/12312312312326/22/ABC/10/DEF/21/GHI")
        cases.generates("https://example.com", "(01)12312312312326(22)ABC(10)DEF(21)GHI(95)INT", "https://example.com/01/12312312312326/22/ABC/10/DEF/21/GHI?95=INT")
